/*
 Problem: 1807. Evaluate the Bracket Pairs of a String
 Language: cpp
 Runtime: 77 ms (63.02%)
 Memory: 122.7 MB (83.44%)
 Tags: Array, Hash Table, String
*/
class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> mp;

        for (const auto& x : knowledge)
            mp[x[0]] = x[1];

        string ans;

        for (int i = 0; i < s.size(); ++i) {
            if (s[i] != '(') {
                ans += s[i];
                continue;
            }

            int j = i + 1;

            while (s[j] != ')')
                ++j;

            const auto key = s.substr(i + 1, j - i - 1);
            const auto it = mp.find(key);

            if (it == mp.end())
                ans += '?';
            else
                ans += it->second;

            i = j;
        }

        return ans;
    }
};
